const $=s=>document.querySelector(s), main=$('#main'), dialog=$('#editor');
let db, exhibitions=[], draft, urls=[];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const url=o=>{let u=URL.createObjectURL(o.blob);urls.push(u);return u};
const cleanup=()=>{urls.forEach(URL.revokeObjectURL);urls=[]};
const samples=[{id:'sample',title:'Somewhere, unhurried.',intro:'A weekend with no particular plans. Just us, a little fresh air, and the long way home.',date:'A WEEKEND AWAY',objects:[{title:'The long way there',note:'We stopped whenever the view asked us to. No schedule. No rush.',src:'assets/lake.jpg',type:'image'},{title:'A little off the path',note:'The whole forest smelled like rain. We forgot to check the time.',src:'assets/forest.jpg',type:'image'},{title:'Small in the best way',note:'One of those places that makes everything else feel a little quieter.',src:'assets/mountains.jpg',type:'image'}]},{id:'sample-forest',title:'A quieter kind of day.',intro:'An afternoon under the trees. Nothing much happened, and that was the best part.',date:'THE LITTLE THINGS',objects:[{title:'Green, everywhere',note:'A reminder to look up more often.',src:'assets/forest.jpg',type:'image'},{title:'The way back',note:'Taking a little of the quiet home with me.',src:'assets/lake.jpg',type:'image'}]},{id:'sample-mountain',title:'Out of the ordinary.',intro:'For a moment, the world felt very big and the to-do list felt very small.',date:'NOTES FROM THE ROAD',objects:[{title:'A different perspective',note:'I want to remember how it felt to stand here.',src:'assets/mountains.jpg',type:'image'}]}];
const sample=samples[0];
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',3500)}
async function init(){try{db=await new Promise((resolve,reject)=>{const r=indexedDB.open('museum-of-you',1);r.onupgradeneeded=()=>r.result.createObjectStore('exhibitions',{keyPath:'id'});r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)});exhibitions=await new Promise((resolve,reject)=>{const r=db.transaction('exhibitions').objectStore('exhibitions').getAll();r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)});exhibitions.sort((a,b)=>(b.updated||0)-(a.updated||0));home()}catch(e){main.innerHTML='<h1>Your journal needs browser storage.</h1><p>Please enable site storage and reload to save your entries.</p>';document.querySelectorAll('[data-new]').forEach(b=>b.disabled=true)}}
let selectedEntry=0, readerPage=0, activeExhibition=null, showOverview=false;
const allEntries=()=>[...exhibitions,...samples];
const isSample=e=>e.id.startsWith('sample');
const source=o=>o.src||url(o);
function visual(o,alt='Journal photograph'){return o?.type==='image'?`<img src="${source(o)}" alt="${esc(o.title||alt)}" draggable="false">`:o?.type==='audio'?'<span class="audio-visual">♫<small>a voice worth keeping</small></span>':'<span class="blank-visual">a little space<br>for something good.</span>'}
function spread(e,interactive=false){const objects=e.objects;return `<div class="spread-left"><div class="photo-one">${visual(objects[0])}</div><span class="paper-tape" aria-hidden="true"></span><span class="sun-doodle" aria-hidden="true">☼</span><div class="small-photo">${objects[1]?visual(objects[1]):'<span class="handwritten">little things,<br>big feelings.</span>'}</div><span class="handwritten left-note">the days I want<br>to remember ↗</span></div><div class="spread-right"><span class="entry-kicker">${esc(e.date||'A PAGE FROM MY LIFE')}</span><h2>${esc(e.title)}</h2><p>${esc(e.intro||'A few things I want to remember.')}</p><div class="photo-two">${visual(objects[2]||objects[1]||objects[0])}</div><span class="flower-doodle" aria-hidden="true">✿</span><span class="handwritten right-note">${isSample(e)?'wish we could stay a little longer.':'a little piece of my life.'}</span><span class="page-number">${isSample(e)?'SAMPLE ENTRY · ':''}${objects.length} ${objects.length===1?'memory':'memories'}</span></div>`}
function home(){cleanup();activeExhibition=null;document.body.classList.remove('reading');const entries=allEntries();selectedEntry=Math.min(selectedEntry,entries.length-1);const e=entries[selectedEntry];main.innerHTML=`<section class="journal-heading"><span class="eyebrow">THE BEAUTIFULLY ORDINARY</span><h1>Your life, <em>in pages.</em></h1><p>A place for the photos, little notes, and days you want to keep.</p></section><section class="journal-desk" aria-label="Your journal entries"><div class="desk-scribble handwritten" aria-hidden="true">a few pages<br>of being you <span>↘</span></div><div class="page-deck"><div class="back-sheet sheet-one" aria-hidden="true"></div><div class="back-sheet sheet-two" aria-hidden="true"></div><div class="back-sheet sheet-three" aria-hidden="true"></div><button class="journal-spread preview-spread" id="open-entry" aria-label="Open ${esc(e.title)}">${spread(e)}</button><span class="book-spine" aria-hidden="true"></span><span class="ribbon" aria-hidden="true"></span></div><div class="desk-caption"><span>${isSample(e)?'A LITTLE INSPIRATION · SAMPLE ENTRY':'YOUR PERSONAL JOURNAL'}</span><strong>${esc(e.title)}</strong><button id="open-text">Open this entry <span>↗</span></button></div></section><div class="journal-controls"><button class="round" id="previous-entry" aria-label="Previous journal entry" ${selectedEntry===0?'disabled':''}>←</button><div><span class="entry-position">${String(selectedEntry+1).padStart(2,'0')} <i>/ ${String(entries.length).padStart(2,'0')}</i></span><span class="control-caption">FLIP THROUGH YOUR ENTRIES</span></div><button class="round" id="next-entry" aria-label="Next journal entry" ${selectedEntry===entries.length-1?'disabled':''}>→</button></div><button class="new-page" data-new><span>＋</span> Add a little of today</button><p class="storage-note">Just for you. Saved in this browser, with no cloud backup.</p><div class="journal-index ${showOverview?'is-open':''}" id="journal-index"><div class="index-head"><span class="eyebrow">ALL YOUR PAGES</span><button id="close-index" aria-label="Close entry list">×</button></div>${entries.map((x,i)=>`<button class="index-entry" data-select="${i}"><span class="index-image">${visual(x.objects[0])}</span><span><strong>${esc(x.title)}</strong><small>${isSample(x)?'Sample entry':x.objects.length+' '+(x.objects.length===1?'memory':'memories')}</small></span><span>↗</span></button>`).join('')}</div>`;$('#open-entry').onclick=$('#open-text').onclick=()=>view(e.id);$('#previous-entry').onclick=()=>turnEntry(-1);$('#next-entry').onclick=()=>turnEntry(1);$('#close-index').onclick=()=>{showOverview=false;$('#journal-index').classList.remove('is-open');updateOverview();$('#overview').focus()};main.querySelectorAll('[data-select]').forEach(b=>b.onclick=()=>{selectedEntry=Number(b.dataset.select);showOverview=false;home()});bind();updateOverview();}
let pageTurning=false;
async function flipSpread(direction,render,selector,focusSelector){
 if(pageTurning)return;
 const oldSpread=$(selector);
 if(!oldSpread||matchMedia('(prefers-reduced-motion: reduce)').matches){render();$(focusSelector)?.focus();return}
 pageTurning=true;document.body.classList.add('page-turning');
 // Keep the outgoing sheet's object URLs alive until both faces have landed.
 const old=oldSpread.cloneNode(true),oldUrls=urls;urls=[];
 let scene;
 try{
 render();const next=$(selector);if(!next)return;
 const host=next.parentElement,forward=direction>0;
 scene=document.createElement('div');scene.className=`page-turn-scene ${forward?'turn-forward':'turn-backward'}`;scene.setAttribute('aria-hidden','true');scene.inert=true;
 const face=(spread,side)=>{const wrap=document.createElement('div');wrap.className=`sheet-content crop-${side}`;const clone=spread.cloneNode(true);clone.removeAttribute('id');clone.querySelectorAll('[id]').forEach(n=>n.removeAttribute('id'));clone.querySelectorAll('audio').forEach(n=>n.remove());clone.classList.remove('preview-spread');clone.classList.add('sheet-spread');clone.style.animation='none';wrap.append(clone);return wrap};
 const stationary=document.createElement('div');stationary.className='stationary-page';stationary.append(face(old,forward?'left':'right'));
 const sheet=document.createElement('div');sheet.className='turning-sheet';
 const front=document.createElement('div');front.className='sheet-face sheet-front';front.append(face(old,forward?'right':'left'));
 const back=document.createElement('div');back.className='sheet-face sheet-back';back.append(face(next,forward?'left':'right'));
 const frontShade=document.createElement('div');frontShade.className='sheet-shading';front.append(frontShade);
 const backShade=document.createElement('div');backShade.className='sheet-shading';back.append(backShade);
 sheet.append(front,back);scene.append(stationary,sheet);host.append(scene);
 const duration=1150,sign=forward?-1:1,options={duration,easing:'cubic-bezier(.32,.05,.2,1)',fill:'forwards'};
 frontShade.animate([{opacity:0},{opacity:.32,offset:.48},{opacity:0}],options);
 backShade.animate([{opacity:.35},{opacity:.22,offset:.55},{opacity:0}],options);
 stationary.animate([{filter:'brightness(1)'},{filter:'brightness(.77)',offset:.5},{filter:'brightness(1)'}],options);
 await sheet.animate([{transform:'rotateY(0deg)'},{transform:`rotateY(${sign*76}deg) rotateZ(${sign*.8}deg)`,offset:.45},{transform:`rotateY(${sign*135}deg) rotateZ(${sign*.35}deg)`,offset:.72},{transform:`rotateY(${sign*180}deg)`}],options).finished;
 }finally{scene?.remove();oldUrls.forEach(URL.revokeObjectURL);pageTurning=false;document.body.classList.remove('page-turning');$(focusSelector)?.focus()}
}
function turnEntry(direction){const target=Math.max(0,Math.min(selectedEntry+direction,allEntries().length-1));if(target===selectedEntry||pageTurning)return;flipSpread(direction,()=>{selectedEntry=target;home()},'.preview-spread','#'+(direction>0?'next-entry':'previous-entry'))}
function bind(){main.querySelectorAll('[data-new]').forEach(b=>b.onclick=()=>edit())}
function updateOverview(){$('#overview').setAttribute('aria-expanded',String(showOverview));if($('#journal-index'))$('#journal-index').inert=!showOverview}
function view(id,index=0){cleanup();const e=allEntries().find(x=>x.id===id);if(!e)return home();activeExhibition=e;readerPage=Math.max(0,Math.min(index,e.objects.length));document.body.classList.add('reading');main.innerHTML=`<div class="reader-top"><button id="back">← Back to journal</button><span>${isSample(e)?'SAMPLE ENTRY':'YOUR JOURNAL'} / ${esc(e.title)}</span>${isSample(e)?'<button data-new>Make your own ＋</button>':'<button id="edit">Edit entry ✎</button>'}</div><section class="reader-desk"><article class="journal-spread reader-spread">${readerPage===0?spread(e):memoryPage(e,readerPage-1)}</article><span class="book-spine" aria-hidden="true"></span></section><div class="journal-controls reader-controls"><button class="round" id="previous-page" aria-label="Previous page" ${readerPage===0?'disabled':''}>←</button><div><span class="entry-position">${readerPage===0?'The whole feeling':'Memory '+readerPage+' of '+e.objects.length}</span><span class="control-caption">${readerPage===0?'TURN THE PAGE · OR SWIPE TO EXPLORE':'A LITTLE MORE TO THE STORY'}</span></div><button class="round" id="next-page" aria-label="Next page" ${readerPage>=e.objects.length?'disabled':''}>→</button></div><div class="reader-dots" aria-label="Journal pages">${Array.from({length:e.objects.length+1},(_,i)=>`<button data-page="${i}" aria-label="${i===0?'Entry overview':'Memory '+i}" aria-current="${readerPage===i?'page':'false'}"></button>`).join('')}</div><p class="storage-note">${isSample(e)?'Fictional sample notes · Landscape photography via Unsplash':'Saved in this browser · No cloud backup'}</p>`;$('#back').onclick=home;$('#previous-page').onclick=()=>turnPage(id,-1);$('#next-page').onclick=()=>turnPage(id,1);main.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{const target=Number(b.dataset.page);if(target!==readerPage)flipSpread(target>readerPage?1:-1,()=>view(id,target),'.reader-spread',`[data-page="${target}"]`)});if($('#edit'))$('#edit').onclick=()=>edit(e);bind();}
function memoryPage(e,i){const o=e.objects[i];return `<div class="memory-photo-page"><div class="memory-photo">${visual(o)}</div><span class="paper-tape" aria-hidden="true"></span><span class="handwritten">${esc(o.title||'a moment worth keeping')}</span></div><div class="memory-note-page"><span class="entry-kicker">A LITTLE MEMORY · ${String(i+1).padStart(2,'0')}</span><h2>${esc(o.title||'Just this moment.')}</h2><p class="memory-note">${esc(o.note||'Sometimes the photo says it all.')}</p>${o.type==='audio'?`<audio controls src="${source(o)}"></audio>`:''}<span class="handwritten">with love, me.</span><span class="pressed-flower" aria-hidden="true">✾</span><span class="page-number">${esc(e.title)}</span></div>`}
function turnPage(id,direction){const e=allEntries().find(x=>x.id===id);if(!e)return;const target=Math.max(0,Math.min(readerPage+direction,e.objects.length));if(target===readerPage||pageTurning)return;flipSpread(direction,()=>view(id,target),'.reader-spread','#'+(direction>0?'next-page':'previous-page'))}
let swipeStart=null;
main.addEventListener('pointerdown',ev=>{if(!activeExhibition||pageTurning||ev.target.closest('button,audio,input,textarea'))return;swipeStart={x:ev.clientX,y:ev.clientY,id:ev.pointerId}});
main.addEventListener('pointerup',ev=>{if(!swipeStart||ev.pointerId!==swipeStart.id)return;const dx=ev.clientX-swipeStart.x,dy=ev.clientY-swipeStart.y;swipeStart=null;if(Math.abs(dx)>45&&Math.abs(dx)>Math.abs(dy)*1.4&&activeExhibition)turnPage(activeExhibition.id,dx<0?1:-1)});
main.addEventListener('pointercancel',()=>swipeStart=null);
document.addEventListener('keydown',ev=>{if(document.querySelector('dialog[open]')||['INPUT','TEXTAREA','BUTTON'].includes(ev.target.tagName))return;if(ev.key==='Escape'){showOverview=false;if($('#journal-index'))$('#journal-index').classList.remove('is-open');updateOverview()}if(ev.key==='ArrowRight')activeExhibition?turnPage(activeExhibition.id,1):turnEntry(1);if(ev.key==='ArrowLeft')activeExhibition?turnPage(activeExhibition.id,-1):turnEntry(-1)});
function edit(e){draft=e?structuredClone(e):{id:crypto.randomUUID(),title:'',intro:'',objects:[]};$('#title').value=draft.title;$('#intro').value=draft.intro;$('#error').textContent='';renderObjects();document.querySelector('.delete-exhibition')?.remove();if(e){const del=document.createElement('button');del.type='button';del.className='delete-exhibition';del.textContent='Delete entry';del.onclick=async()=>{if(!confirm('Delete this entry and its memories? This cannot be undone.'))return;try{await write('delete',e.id);exhibitions=exhibitions.filter(x=>x.id!==e.id);dialog.close();home();toast('Entry deleted')}catch{$('#error').textContent='Could not delete. Please try again.'}};$('#form').append(del)}dialog.showModal();$('#title').focus()}
function renderObjects(){const list=$('#objects');list.replaceChildren();$('#count').textContent=`${draft.objects.length} ${draft.objects.length===1?'memory':'memories'} added`;draft.objects.forEach((o,i)=>{const el=document.createElement('div');el.className='object-edit';el.innerHTML=`${o.type==='image'?`<img src="${url(o)}" alt="Photo preview">`:'<span class="cover-audio">♫</span>'}<div><input aria-label="Memory ${i+1} title" maxlength="100" placeholder="Caption (optional)" value="${esc(o.title)}"><textarea aria-label="Memory ${i+1} note" maxlength="2000" rows="2" placeholder="What would you like to remember about this?">${esc(o.note)}</textarea><div class="object-actions"><button type="button" data-up ${i===0?'disabled':''}>↑ Move earlier</button><button type="button" data-down ${i===draft.objects.length-1?'disabled':''}>↓ Move later</button><button type="button" data-remove>Remove</button></div></div>${o.type==='audio'?`<audio controls src="${url(o)}"></audio>`:''}`;el.querySelector('input').oninput=ev=>o.title=ev.target.value;el.querySelector('textarea').oninput=ev=>o.note=ev.target.value;el.querySelector('[data-remove]').onclick=()=>{draft.objects.splice(i,1);renderObjects()};el.querySelector('[data-up]').onclick=()=>{[draft.objects[i-1],draft.objects[i]]=[draft.objects[i],draft.objects[i-1]];renderObjects()};el.querySelector('[data-down]').onclick=()=>{[draft.objects[i+1],draft.objects[i]]=[draft.objects[i],draft.objects[i+1]];renderObjects()};list.append(el)})}
$('#upload').onchange=ev=>{const errors=[];for(const f of ev.target.files){if(!/^(image|audio)\//.test(f.type)){errors.push(`${f.name}: choose an image or audio file.`);continue}if(f.size>20*1024*1024){errors.push(`${f.name}: exceeds 20 MB.`);continue}draft.objects.push({id:crypto.randomUUID(),type:f.type.startsWith('image/')?'image':'audio',blob:f,title:'',note:''})}$('#error').textContent=errors.join(' ');ev.target.value='';renderObjects()};
function write(method,value){return new Promise((resolve,reject)=>{const tx=db.transaction('exhibitions','readwrite');tx.objectStore('exhibitions')[method](value);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error)})}
$('#form').onsubmit=async ev=>{ev.preventDefault();const b=ev.submitter;b.disabled=true;draft.title=$('#title').value.trim()||'Untitled entry';draft.intro=$('#intro').value.trim();draft.updated=Date.now();try{await write('put',draft);const idx=exhibitions.findIndex(e=>e.id===draft.id);if(idx>=0)exhibitions[idx]=draft;else exhibitions.unshift(draft);dialog.close();view(draft.id);toast('Journal entry saved on this browser')}catch{$('#error').textContent='Could not save. Browser storage may be full. Your edits are still here; try removing a large file.'}finally{b.disabled=false}};
function closeEditor(){if(confirm('Close without saving these edits?')){dialog.close();home()}}
$('#close').onclick=closeEditor;dialog.addEventListener('cancel',e=>{e.preventDefault();closeEditor()});document.querySelector('header [data-new]').onclick=()=>edit();$('#overview').onclick=()=>{if(activeExhibition){showOverview=true;home()}else{showOverview=!showOverview;$('#journal-index').classList.toggle('is-open',showOverview);updateOverview()}};document.querySelectorAll('header a').forEach(a=>a.onclick=e=>{e.preventDefault();home()});init();
